cat > /etc/nginx/conf.d/inventory-lb.conf <<'EOF'
upstream inventory_backend {
    server 10.100.21.11:8080 max_fails=3 fail_timeout=10s;
    server 10.100.21.12:8080 max_fails=3 fail_timeout=10s;
}

server {
    listen 80 default_server;
    server_name _;

    location / {
        proxy_pass http://inventory_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_connect_timeout 3s;
        proxy_next_upstream error timeout http_502 http_503 http_504;
    }
}
EOF
